public void callAPI()
{
    Map configMap = new Map(Types::String, Types::String);


    XAPI_APILogTable logTable;

    select firstonly logTable
        where logTable.ApiName == XAPI_APIS::CreateCustomer
           && logTable.Key == 'CustAccount';

    if (!logTable.RecId)
    {
        throw error("Customer account not found in log.");
    }

    configMap.insert('<custAccount>', logTable.Value);



    this.prepareBody(configMap);
    this.sendPostRequest();

    if (responseText == '')
    {
        return;
    }

    EGS_API_DataContract_Response res =
        FormJsonSerializer::deserializeObject(
            classNum(EGS_API_DataContract_Response),
            responseText);

    if (res != null)
    {
        this.log("ContactInfoResponse", res.parmMessage());
    }
}
